/// AvailableCalendars ( ): the calendars of `icu::calendar` (one per
/// `AnyCalendarKind` with a CLDR calendar type), with their aliases, sorted.
fn available_calendars() -> Vec<&'static str> {
    let mut list: Vec<&'static str> = Vec::new();
    for kind in [
        AnyCalendarKind::Buddhist,
        AnyCalendarKind::Chinese,
        AnyCalendarKind::Coptic,
        AnyCalendarKind::Dangi,
        AnyCalendarKind::Ethiopian,
        AnyCalendarKind::EthiopianAmeteAlem,
        AnyCalendarKind::Gregorian,
        AnyCalendarKind::Hebrew,
        AnyCalendarKind::Indian,
        AnyCalendarKind::HijriTabularTypeIIFriday,
        AnyCalendarKind::HijriTabularTypeIIThursday,
        AnyCalendarKind::HijriUmmAlQura,
        AnyCalendarKind::Iso,
        AnyCalendarKind::Japanese,
        AnyCalendarKind::Persian,
        AnyCalendarKind::Roc,
    ] {
        let (type_, aliases): (&str, &[&str]) = match kind {
            AnyCalendarKind::Buddhist => ("buddhist", &[]),
            AnyCalendarKind::Chinese => ("chinese", &[]),
            AnyCalendarKind::Coptic => ("coptic", &[]),
            AnyCalendarKind::Dangi => ("dangi", &[]),
            AnyCalendarKind::Ethiopian => ("ethiopic", &[]),
            AnyCalendarKind::EthiopianAmeteAlem => ("ethioaa", &["ethiopic-amete-alem"]),
            AnyCalendarKind::Gregorian => ("gregory", &[]),
            AnyCalendarKind::Hebrew => ("hebrew", &[]),
            AnyCalendarKind::Indian => ("indian", &[]),
            AnyCalendarKind::HijriTabularTypeIIFriday => ("islamic-civil", &["islamicc"]),
            AnyCalendarKind::HijriTabularTypeIIThursday => ("islamic-tbla", &[]),
            AnyCalendarKind::HijriUmmAlQura => ("islamic-umalqura", &[]),
            AnyCalendarKind::Iso => ("iso8601", &[]),
            AnyCalendarKind::Japanese => ("japanese", &[]),
            AnyCalendarKind::Persian => ("persian", &[]),
            AnyCalendarKind::Roc => ("roc", &[]),
            _ => continue,
        };
        list.push(type_);
        list.extend_from_slice(aliases);
    }
    list.sort_unstable();
    list
}

/// Lists the numbering systems of ICU4X's baked decimal digits data.
struct BakedDigits;

const _: () = {
    use icu_decimal_data::{__impl_decimal_digits_v1, make_provider};
    make_provider!(BakedDigits);
    __impl_decimal_digits_v1!(BakedDigits, ITER);
};

/// AvailableCanonicalNumberingSystems ( ): the numbering systems with digits
/// in ICU4X's decimal data, sorted.
fn available_canonical_numbering_systems() -> Vec<String> {
    let ids = IterableDataProvider::<icu::decimal::provider::DecimalDigitsV1>::iter_ids(
        &BakedDigits,
    );
    let mut list: Vec<String> = ids
        .into_iter()
        .flatten()
        .map(|id| id.marker_attributes.as_str().to_string())
        .filter(|s| !s.is_empty())
        .collect();
    list.sort();
    list.dedup();
    list
}

/// AvailablePrimaryTimeZoneIdentifiers ( ): the canonical IANA identifiers of
/// `icu::time`, sorted.
fn available_primary_time_zone_identifiers() -> Vec<String> {
    // 1. Let _records_ be AvailableNamedTimeZoneIdentifiers().
    // 2. Let _result_ be a new empty List.
    // 3. For each element _timeZoneIdentifierRecord_ of _records_, do
    //    a. If [[Identifier]] is [[PrimaryIdentifier]], then append [[Identifier]].
    // (ICU4X's canonical IANA identifiers are the primary ones.)
    let parser = IanaParserExtended::new();
    let mut result: Vec<String> = parser
        .iter()
        .map(|t| match t.canonical {
            // c. If _primary_ is one of "Etc/UTC", "Etc/GMT", or "GMT", set _primary_ to "UTC".
            "Etc/UTC" | "Etc/GMT" | "GMT" => "UTC".to_string(),
            other => other.to_string(),
        })
        .collect();
    // 4. Return _result_.
    result.sort();
    result.dedup();
    result
}""")
